fixture={'tests/test_workflow_finalization_resilience.py': '"""Resilience contracts for sealed workflow finalization."""\n\nfrom __future__ import annotations\n\nimport time\nfrom dataclasses import fields\n\nimport pytest\n\nfrom minicode import workflow_finalization\nfrom minicode.central_scheduler import (\n    CentralScheduler,\n    TaskKind,\n    TaskProfile,\n    TaskRisk,\n)\nfrom minicode.tooling import ToolResult\nfrom minicode.turn_cancellation import TurnCancellationRequested\n\n\ndef _read_only_snapshot() -> workflow_finalization._WorkflowFinalizationSnapshot:\n    profile = TaskProfile(\n        task_id="task_finalization_resilience",\n        kind=TaskKind.READ_ONLY,\n        risk=TaskRisk.LOW,\n        parent_has_sufficient_context=True,\n        scope_clear=True,\n    )\n    scheduler = CentralScheduler()\n    plan = scheduler.plan(profile)\n    transitions = []\n\n    def forbidden_execution_capability(*_args, **_kwargs):\n        raise AssertionError("the parent-only route cannot execute a phase port")\n\n    outcome = scheduler.execute(\n        profile,\n        workflow_id="wf_finalization_resilience",\n        run_worker=forbidden_execution_capability,\n        run_verifier=forbidden_execution_capability,\n        commit=forbidden_execution_capability,\n        on_transition=transitions.append,\n    )\n    capture_kwargs = {\n        "description": "finalization resilience",\n        "subagent_id": "sub_" + "a" * 32,\n        "started_at": time.time(),\n        "contract_mode": "legacy",\n        "profile": profile,\n        "dispatch_plan": plan,\n        "scheduler_outcome": outcome,\n        "transitions": transitions,\n        "artifacts": [],\n        "explore_results": [],\n        "plan_result": None,\n        "execute_result": None,\n        "review_result": None,\n        "analyst_report": None,\n        "execution_artifact": None,\n        "verification_result": None,\n        "typed_review": {\n            "reviewVersion": 1,\n            "verdict": "not_applicable",\n            "blockingFindings": [],\n            "warnings": [],\n        },\n        "approval_request_id": None,\n        "commit_ready_status": "not_applicable",\n        "commit_error_text": None,\n        "production_audit_required": False,\n        "initial_finalization_status": "completed",\n    }\n    return workflow_finalization._WorkflowFinalizationSnapshot.capture(**capture_kwargs)\n\n\ndef _direct_snapshot_values() -> dict[str, object]:\n    snapshot = _read_only_snapshot()\n    return {field.name: getattr(snapshot, field.name) for field in fields(snapshot)}\n\n\ndef test_uncommitted_audit_persistence_cancellation_propagates() -> None:\n    cancellation = TurnCancellationRequested("turn_" + "b" * 32)\n\n    def cancel_during_audit(_audit: object) -> object:\n        raise cancellation\n\n    with pytest.raises(TurnCancellationRequested) as caught:\n        workflow_finalization.finalize_workflow(\n            _read_only_snapshot(),\n            workflow_finalization._WorkflowFinalizationPorts(\n                checkpoint=lambda: None,\n                persist_audit=cancel_during_audit,\n                observe=lambda _observation: None,\n            ),\n        )\n\n    assert caught.value is cancellation\n\n\ndef test_phase_result_snapshot_rejects_tool_result_subclasses() -> None:\n    class DerivedToolResult(ToolResult):\n        pass\n\n    with pytest.raises(TypeError):\n        workflow_finalization._PhaseResultSnapshot.from_result(\n            DerivedToolResult(ok=True, output="subclass output")\n        )\n\n\ndef test_direct_snapshot_rejects_invalid_initial_finalization_status() -> None:\n    values = _direct_snapshot_values()\n    values["initial_finalization_status"] = "execution_still_active"\n\n    with pytest.raises(ValueError):\n        workflow_finalization._WorkflowFinalizationSnapshot(**values)\n\n\ndef test_direct_snapshot_rejects_mutable_commit_error() -> None:\n    values = _direct_snapshot_values()\n    values["commit_error_text"] = RuntimeError("mutable execution error")\n\n    with pytest.raises(TypeError):\n        workflow_finalization._WorkflowFinalizationSnapshot(**values)\n', 'conftest.py': '"""Pytest collection controls for repository-local legacy smoke scripts."""\n\nfrom __future__ import annotations\n\nimport logging\nimport os\nimport sys\nfrom pathlib import Path\n\nimport pytest\n\nfrom tests.global_state_isolation import (\n    FormalStateChanged,\n    GlobalStateGuard,\n    IsolatedTestHome,\n    assert_minicode_not_preloaded,\n)\n\n\n_REAL_HOME = Path(\n    os.environ.get("MINICODE_PYTEST_REAL_HOME")\n    or os.environ.get("HOME")\n    or Path.home()\n).expanduser().resolve()\nassert_minicode_not_preloaded(sys.modules, real_home=_REAL_HOME)\n_TEST_HOME = IsolatedTestHome.create(real_home=_REAL_HOME, environ=os.environ)\n\n\n_REAL_MINICODE_DIR = _REAL_HOME / ".mini-code"\n_PROTECTED_REAL_PATHS = (\n    _REAL_MINICODE_DIR / "memory" / "memory.json",\n    _REAL_MINICODE_DIR / "memory" / "MEMORY.md",\n    _REAL_MINICODE_DIR / "memory" / "approval_audit.json",\n    _REAL_MINICODE_DIR / "sessions_index.json",\n    _REAL_MINICODE_DIR / ".env",\n    _REAL_MINICODE_DIR / "settings.json",\n    _REAL_MINICODE_DIR / "history.json",\n    _REAL_MINICODE_DIR / "context_state.json",\n    _REAL_MINICODE_DIR / "USER.md",\n    _REAL_MINICODE_DIR / "permissions.json",\n    _REAL_MINICODE_DIR / "mcp.json",\n    _REAL_MINICODE_DIR / "minicode.log",\n    _REAL_MINICODE_DIR / "cybernetic_supervisor.json",\n)\n_REAL_HOME_GUARD = GlobalStateGuard(\n    _PROTECTED_REAL_PATHS,\n    protected_roots=(_REAL_MINICODE_DIR,),\n)\n_REAL_HOME_GUARD_FAILURE: str | None = None\n\n\n# These root-level scripts are manual smoke/integration utilities from earlier\n# development rounds. Normal pytest coverage lives under tests/.\ncollect_ignore = [\n    "smoke_test.py",\n    "test_chinese_input.py",\n    "test_integration.py",\n    "test_optim.py",\n    "test_run.py",\n    "test_state_integration.py",\n    "visual_test.py",\n]\n\ncollect_ignore_glob = [\n    "benchmarks/*.py",\n]\n\n\ndef _reset_imported_process_state() -> None:\n    logger = logging.getLogger("minicode")\n    for handler in logger.handlers[:]:\n        handler.close()\n        logger.removeHandler(handler)\n    history_module = sys.modules.get("minicode.history")\n    if history_module is not None:\n        setattr(history_module, "_history_cache", None)\n    context_module = sys.modules.get("minicode.context_manager")\n    token_cache = getattr(context_module, "_token_cache", None) if context_module else None\n    if isinstance(token_cache, dict):\n        token_cache.clear()\n\n\ndef pytest_sessionstart(session: pytest.Session) -> None:\n    _REAL_HOME_GUARD.capture_start()\n\n\ndef pytest_sessionfinish(session: pytest.Session, exitstatus: int) -> None:\n    global _REAL_HOME_GUARD_FAILURE\n    try:\n        _REAL_HOME_GUARD.assert_unchanged()\n    except FormalStateChanged as exc:\n        _REAL_HOME_GUARD_FAILURE = str(exc)\n        session.exitstatus = pytest.ExitCode.TESTS_FAILED\n\n\ndef pytest_terminal_summary(terminalreporter: pytest.TerminalReporter) -> None:\n    if _REAL_HOME_GUARD_FAILURE:\n        terminalreporter.write_sep("=", "REAL HOME POLLUTION DETECTED")\n        terminalreporter.write_line(_REAL_HOME_GUARD_FAILURE)\n\n\ndef pytest_unconfigure(config: pytest.Config) -> None:\n    _reset_imported_process_state()\n    _TEST_HOME.cleanup()\n\n\n@pytest.fixture(autouse=True)\ndef _isolate_minicode_state_per_test():\n    _reset_imported_process_state()\n    _TEST_HOME.reset()\n    yield\n    _reset_imported_process_state()\n    _TEST_HOME.reset()\n\n\n@pytest.fixture\ndef minicode_test_home() -> Path:\n    return _TEST_HOME.home\n\n\n@pytest.fixture\ndef minicode_real_home() -> Path:\n    return _REAL_HOME\n\n\n@pytest.fixture\ndef memory_manager(tmp_path):\n    """Create a MemoryManager with temporary paths."""\n    from minicode.memory import MemoryManager\n    return MemoryManager(project_root=tmp_path)\n\n\n@pytest.fixture\ndef memory_with_entries(memory_manager):\n    """Create a MemoryManager pre-populated with test entries."""\n    from minicode.memory import MemoryScope\n    entries = [\n        ("project", "architecture", "Uses FastAPI for REST API backend", ["api", "fastapi"]),\n        ("project", "code-pattern", "All functions use snake_case naming", ["convention", "naming"]),\n        ("project", "testing", "Tests use pytest with fixtures", ["test", "pytest"]),\n        ("user", "preference", "Always respond in Chinese", ["language", "chinese"]),\n        ("local", "decision", "Use SQLite for development database", ["database", "sqlite"]),\n    ]\n    for scope, category, content, tags in entries:\n        memory_manager.add_entry(\n            MemoryScope(scope), category, content, tags\n        )\n    return memory_manager\n\n\n@pytest.fixture\ndef mock_memory_search():\n    """Mock search function for testing prompt injection."""\n    def mock_search(query, scope=None, limit=20, min_relevance=0.1):\n        from minicode.memory import MemoryEntry, MemoryScope\n        return [\n            MemoryEntry(id="test-1", scope=MemoryScope.PROJECT, category="test", content=f"Mock result for: {query}"),\n        ]\n    return mock_search\n\n\n@pytest.fixture\ndef temp_workspace(tmp_path):\n    """Create a temporary workspace with basic structure."""\n    workspace = tmp_path / "workspace"\n    workspace.mkdir()\n    (workspace / "src").mkdir()\n    (workspace / "tests").mkdir()\n    (workspace / "src" / "main.py").write_text("# Main file\\n")\n    return str(workspace)\n', 'pyproject.toml': '[build-system]\nrequires = ["setuptools>=68", "wheel"]\nbuild-backend = "setuptools.build_meta"\n\n[project]\nname = "minicode-py"\nversion = "0.1.0"\ndescription = "A lightweight terminal coding assistant for local development workflows."\nreadme = "README.md"\nrequires-python = ">=3.11"\ndependencies = [\n    "certifi>=2025.7.14,<2027",\n]\n\n[project.optional-dependencies]\ndev = [\n    "jsonschema>=4.0.0",\n    "pytest>=8.0.0",\n    "ruff>=0.9.0,<1",\n    "setuptools>=68",\n    "wheel",\n]\nmemory-hybrid = [\n    "huggingface-hub>=0.33.4,<1",\n    "numpy>=2.0.0,<3",\n    "onnxruntime>=1.22.0,<2",\n    "tokenizers>=0.21.0,<1",\n]\n\n[project.scripts]\nminicode-py = "minicode.main:main"\nminicode-gateway = "minicode.gateway:run_gateway"\nminicode-cron = "minicode.cron_runner:main"\nminicode-headless = "minicode.headless:main"\n\n[tool.pytest.ini_options]\npythonpath = ["."]\ntestpaths = ["tests"]\nmarkers = [\n    "benchmark: performance-oriented regression test",\n]\n\n[tool.setuptools]\npackage-dir = {"" = "."}\n\n[tool.setuptools.packages.find]\nwhere = ["."]\ninclude = ["minicode*"]\nnamespaces = false\n\n[tool.setuptools.package-data]\n"minicode.web" = [\n    "static/*.html",\n    "static/assets/*.css",\n    "static/assets/*.js",\n]\n', 'tests/global_state_isolation.py': '"""Test-only process HOME isolation and formal-state guards."""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nimport os\nimport re\nimport shutil\nimport tempfile\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom typing import Any, Iterable, Mapping, MutableMapping\n\n\nTEST_MODEL = "claude-sonnet-4-20250514"\nTEST_AUTH_TOKEN = "pytest-mock-auth-not-a-secret"\n_CREDENTIAL_ENV_NAMES = (\n    "MINI_CODE_PROVIDER",\n    "ANTHROPIC_API_KEY",\n    "ANTHROPIC_AUTH_TOKEN",\n    "ANTHROPIC_BASE_URL",\n    "ANTHROPIC_MODEL",\n    "OPENAI_API_KEY",\n    "OPENAI_API_BASE",\n    "OPENAI_BASE_URL",\n    "OPENROUTER_API_KEY",\n    "OPENROUTER_BASE_URL",\n    "CUSTOM_API_KEY",\n    "CUSTOM_API_BASE_URL",\n    "DEEPSEEK_BASE_URL",\n    "DEEPSEEK_API_KEY",\n)\n\n\ndef _sha256(path: Path) -> str:\n    digest = hashlib.sha256()\n    with path.open("rb") as stream:\n        for chunk in iter(lambda: stream.read(1024 * 1024), b""):\n            digest.update(chunk)\n    return digest.hexdigest()\n\n\ndef snapshot_paths(paths: list[Path] | tuple[Path, ...]) -> dict[str, dict[str, Any]]:\n    """Capture only existence, hash, size, and mtime for protected files."""\n    snapshot: dict[str, dict[str, Any]] = {}\n    for raw_path in paths:\n        path = Path(raw_path).expanduser().absolute()\n        if not path.exists():\n            snapshot[str(path)] = {"exists": False, "sha256": None, "size": None, "mtime_ns": None}\n            continue\n        metadata = path.stat()\n        snapshot[str(path)] = {\n            "exists": True,\n            "sha256": _sha256(path),\n            "size": metadata.st_size,\n            "mtime_ns": metadata.st_mtime_ns,\n        }\n    return snapshot\n\n\ndef compare_snapshots(\n    before: Mapping[str, Mapping[str, Any]],\n    after: Mapping[str, Mapping[str, Any]],\n) -> list[dict[str, Any]]:\n    """Return privacy-safe path/change summaries without file content."""\n    changes: list[dict[str, Any]] = []\n    for path in sorted(set(before) | set(after)):\n        old = before.get(path, {"exists": False})\n        new = after.get(path, {"exists": False})\n        old_exists = bool(old.get("exists"))\n        new_exists = bool(new.get("exists"))\n        kinds: list[str] = []\n        if old_exists != new_exists:\n            kinds.append("created" if new_exists else "deleted")\n        elif old_exists:\n            if old.get("sha256") != new.get("sha256"):\n                kinds.append("content_hash")\n            if old.get("size") != new.get("size"):\n                kinds.append("size")\n            if old.get("mtime_ns") != new.get("mtime_ns"):\n                kinds.append("mtime_ns")\n        if kinds:\n            changes.append({"path": path, "changes": kinds})\n    return changes\n\n\nclass FormalStateChanged(RuntimeError):\n    """Raised when a protected real-home file changes during pytest."""\n\n\nclass GlobalStateGuard:\n    """Hash/stat guard that detects formal-state changes and never rolls back."""\n\n    def __init__(\n        self,\n        protected_paths: list[Path] | tuple[Path, ...],\n        *,\n        protected_roots: list[Path] | tuple[Path, ...] = (),\n    ) -> None:\n        self._protected_paths = tuple(Path(path) for path in protected_paths)\n        self._protected_roots = tuple(Path(path) for path in protected_roots)\n        self._start: dict[str, dict[str, Any]] | None = None\n\n    @property\n    def start_snapshot(self) -> dict[str, dict[str, Any]] | None:\n        return self._start\n\n    def _capture(self, include_paths: Iterable[str] = ()) -> dict[str, dict[str, Any]]:\n        paths = set(self._protected_paths)\n        paths.update(Path(path) for path in include_paths)\n        for root in self._protected_roots:\n            if root.exists():\n                paths.update(path for path in root.rglob("*") if path.is_file())\n        return snapshot_paths(tuple(sorted(paths)))\n\n    def capture_start(self) -> None:\n        self._start = self._capture()\n\n    def assert_unchanged(self) -> None:\n        if self._start is None:\n            raise RuntimeError("formal-state guard start snapshot was not captured")\n        changes = compare_snapshots(self._start, self._capture(self._start))\n        if changes:\n            summary = "; ".join(\n                f"{item[\'path\']} ({\',\'.join(item[\'changes\'])})" for item in changes\n            )\n            raise FormalStateChanged(f"protected real-home state changed: {summary}")\n\n\ndef assert_minicode_not_preloaded(\n    modules: Mapping[str, object],\n    *,\n    real_home: Path,\n) -> None:\n    """Fail before collection if MiniCode observed the real HOME already."""\n    preloaded = sorted(name for name in modules if name == "minicode" or name.startswith("minicode."))\n    if preloaded:\n        raise RuntimeError(\n            "minicode modules were loaded before pytest HOME isolation: "\n            f"{\', \'.join(preloaded)}; protected real home: {real_home}"\n        )\n\n\ndef _safe_worker_name(worker_id: str) -> str:\n    return re.sub(r"[^A-Za-z0-9_.-]", "_", worker_id) or "main"\n\n\n@dataclass\nclass IsolatedTestHome:\n    """One process/xdist-worker HOME whose global state is reset per test."""\n\n    real_home: Path\n    home: Path\n    settings_path: Path\n    environ: MutableMapping[str, str]\n\n    @classmethod\n    def create(\n        cls,\n        *,\n        real_home: Path,\n        environ: MutableMapping[str, str],\n        temp_root: Path | None = None,\n        process_id: int | None = None,\n        worker_id: str | None = None,\n    ) -> "IsolatedTestHome":\n        pid = process_id if process_id is not None else os.getpid()\n        worker = _safe_worker_name(worker_id or environ.get("PYTEST_XDIST_WORKER", "main"))\n        if temp_root is not None:\n            Path(temp_root).mkdir(parents=True, exist_ok=True)\n        home = Path(\n            tempfile.mkdtemp(\n                prefix=f"minicode-pytest-{pid}-{worker}-",\n                dir=str(temp_root) if temp_root is not None else None,\n            )\n        ).resolve()\n        os.chmod(home, 0o700)\n\n        for name in _CREDENTIAL_ENV_NAMES:\n            environ.pop(name, None)\n        environ.update(\n            {\n                "HOME": str(home),\n                "USERPROFILE": str(home),\n                "XDG_CONFIG_HOME": str(home / ".config"),\n                "MINI_CODE_MODEL_MODE": "mock",\n                "MINI_CODE_SHOW_GUIDE": "0",\n                "MINI_CODE_TOOL_PROFILE": "core",\n                "MINI_CODE_MODEL": TEST_MODEL,\n                "ANTHROPIC_AUTH_TOKEN": TEST_AUTH_TOKEN,\n                "MINICODE_PYTEST_REAL_HOME": str(real_home.resolve()),\n                "MINICODE_PYTEST_ISOLATED_HOME": str(home),\n            }\n        )\n        isolation = cls(\n            real_home=real_home.resolve(),\n            home=home,\n            settings_path=home / ".mini-code" / "settings.json",\n            environ=environ,\n        )\n        isolation.reset()\n        return isolation\n\n    def reset(self) -> None:\n        """Restore a deterministic empty MiniCode home while preserving config."""\n        if self.home.exists():\n            for child in self.home.iterdir():\n                if child.is_dir() and not child.is_symlink():\n                    shutil.rmtree(child)\n                else:\n                    child.unlink()\n        else:\n            self.home.mkdir(parents=True, mode=0o700)\n        os.chmod(self.home, 0o700)\n        (self.home / ".config").mkdir(mode=0o700)\n        self.settings_path.parent.mkdir(mode=0o700)\n        self.settings_path.write_text(\n            json.dumps({"model": TEST_MODEL, "toolProfile": "core"}, sort_keys=True) + "\\n",\n            encoding="utf-8",\n        )\n        os.chmod(self.settings_path, 0o600)\n\n    def cleanup(self) -> None:\n        if self.home.exists():\n            shutil.rmtree(self.home)\n'}
selectors=['tests/test_workflow_finalization_resilience.py::test_uncommitted_audit_persistence_cancellation_propagates', 'tests/test_workflow_finalization_resilience.py::test_phase_result_snapshot_rejects_tool_result_subclasses', 'tests/test_workflow_finalization_resilience.py::test_direct_snapshot_rejects_invalid_initial_finalization_status', 'tests/test_workflow_finalization_resilience.py::test_direct_snapshot_rejects_mutable_commit_error']
with tempfile.TemporaryDirectory(prefix="codeloop-private-oracle-") as temp:
    judge=pathlib.Path(temp)/"workspace"
    shutil.copytree(workspace,judge,ignore=shutil.ignore_patterns("__pycache__",".git",".mini-code"))
    for path,text in fixture.items():
        target=judge/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(text)
    env={k:v for k,v in os.environ.items() if not any(t in k.upper() for t in ("API_KEY","SECRET","PASSWORD","ACCESS_TOKEN","AUTH_TOKEN"))}
    env["PYTHONPATH"]=str(judge);env["PYTHONDONTWRITEBYTECODE"]="1";env["PYTEST_DISABLE_PLUGIN_AUTOLOAD"]="1"
    receipt=pathlib.Path(temp)/"receipt.xml"
    argv=[sys.executable,"-B","-m","pytest","-q","-p","no:cacheprovider",f"--junitxml={receipt}",*selectors]
    result=subprocess.run(argv,cwd=judge,env=env,capture_output=True,text=True,timeout=170)
    print(result.stdout);print(result.stderr,file=sys.stderr)
    assert result.returncode==0, "historical acceptance failed"
    cases=ET.parse(receipt).getroot().findall(".//testcase")
    assert cases and all(c.find("skipped") is None and c.find("failure") is None and c.find("error") is None for c in cases), "incomplete acceptance"
